import sys
d = sys.stdin.read().split()
n = int(d[0])
P = [(int(d[1 + 2 * i]), int(d[2 + 2 * i])) for i in range(n)]
best = 0
for mask in range(1 << n):
    ch = [P[i] for i in range(n) if mask >> i & 1]
    if len(ch) <= best:
        continue
    ok = True
    for i in range(len(ch)):
        for j in range(i + 1, len(ch)):
            (a1, b1), (a2, b2) = ch[i], ch[j]
            if (a1 < a2 and b1 > b2) or (a1 > a2 and b1 < b2):
                ok = False
                break
        if not ok:
            break
    if ok:
        best = len(ch)
print(best)

